def is_multiply_prime(a: int) -> bool:
    """Returns True if the given number is the multiplication of 3 prime numbers, False otherwise."""

    def is_prime(n: int) -> bool:
        """Helper function to check if a number is prime."""
        if n <= 1:
            return False
        if n <= 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    # Check if a is less than 100
    if a < 100:
        # Find all prime numbers up to a
        primes = [i for i in range(2, a) if is_prime(i)]

        # Check if a can be formed by the product of three prime numbers
        for i in range(len(primes)):
            for j in range(i + 1, len(primes)):
                for k in range(j + 1, len(primes)):
                    if primes[i] * primes[j] * primes[k] == a:
                        return True
        return False
    else:
        return False
```

