from datetime import datetime

def valid_date(date: str) -> bool:
    """Validate a date string in the format mm-dd-yyyy."""

    # Check if the date string is not empty
    if not date:
        return False

    # Check if the date string is in the correct format
    try:
        datetime.strptime(date, '%m-%d-%Y')
    except ValueError:
        return False

    # Split the date into month, day, and year
    month, day, year = map(int, date.split('-'))

    # Check if the month is valid
    if not 1 <= month <= 12:
        return False

    # Check if the day is valid based on the month
    if month in [1, 3, 5, 7, 8, 10, 12]:
        if not 1 <= day <= 31:
            return False
    elif month in [4, 6, 9, 11]:
        if not 1 <= day <= 30:
            return False
    elif month == 2:
        if not 1 <= day <= 29:
            return False

    # If all checks pass, the date is valid
    return True
```

This function first checks if the date string is not empty. It then attempts to parse the date string into a `datetime` object using the `strptime` method with the format `'%m-%d-%Y'`. If the parsing fails, the function returns `False`. If the parsing succeeds, it splits the date into month, day, and year, and then checks if the month and day are valid based on the rules provided. If all checks pass, the function returns `True`.

