def comb_sort(lst):
    def is_sorted(lst):
        return all(lst[i] <= lst[i+1] for i in range(len(lst)-1))

    if is_sorted(lst):
        return lst

    gap = len(lst) // 2
    while gap > 0:
        for i in range(len(lst) - gap):
            if lst[i] > lst[i + gap]:
                lst[i], lst[i + gap] = lst[i + gap], lst[i]
        gap //= 2

    return lst

