def pancake_sort(lst):
    n = len(lst)
    for i in range(n - 1, -1, -1):
        max_idx = lst.index(max(lst[:i + 1]))
        if max_idx == i:
            continue
        if max_idx != 0:
            lst[:max_idx + 1] = lst[:max_idx + 1][::-1]
        lst[:i + 1] = lst[:i + 1][::-1]
    return lst

