def find_solution(a, b, n):
    if a == 0 and b == 0 and n != 0:
        return None
    if a == 0:
        if n % b == 0:
            return (0, n // b)
        else:
            return None
    if b == 0:
        if n % a == 0:
            return (n // a, 0)
        else:
            return None
    gcd, x, y = extended_euclidean(a, b)
    if n % gcd != 0:
        return None
    return (x * (n // gcd), y * (n // gcd))

def extended_euclidean(a, b):
    if a == 0:
        return b, 0, 1
    else:
        gcd, x, y = extended_euclidean(b % a, a)
        return gcd, y - (b // a) * x, x

