        for j in range(i, 0, -1):
            for k in range(j - 1, -1, -1):
                if is_divisible(numbers[i - 1], numbers[k]) and dp[i - 1][k]:
                    dp[i][j] = True
                if dp[i - 1][j]:
                    dp[i][j] = True

    max_size = 0
    for i in range(n, 0, -1):
        if dp[n][i]:
